CREATE OR REPLACE FUNCTION public.fin_reset_backups() RETURNS TABLE(id uuid,reset_at timestamptz,counts jsonb) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được xem bản sao reset'; END IF; RETURN QUERY SELECT b.id,b.reset_at,b.counts FROM private.fin_reset_backups b ORDER BY b.reset_at DESC; END; $$;
CREATE OR REPLACE FUNCTION public.fin_reset_backup_get(_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE result jsonb; BEGIN IF NOT private.fin_super(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin được tải bản sao reset'; END IF; SELECT to_jsonb(b) INTO result FROM private.fin_reset_backups b WHERE b.id=_id; IF result IS NULL THEN RAISE EXCEPTION 'Không tìm thấy bản sao'; END IF; RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.fin_reset_backups() FROM PUBLIC,anon;
REVOKE ALL ON FUNCTION public.fin_reset_backup_get(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fin_reset_backups() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fin_reset_backup_get(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.fin_reset_execute(_confirm text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE me uuid:=auth.uid(); ts timestamptz; c jsonb; bid uuid; BEGIN IF NOT private.fin_super(me) THEN RAISE EXCEPTION 'Chỉ Super Admin được reset dữ liệu Tiền Về'; END IF; IF _confirm IS DISTINCT FROM 'RESET TIEN VE' THEN RAISE EXCEPTION 'Nhập đúng RESET TIEN VE để xác nhận'; END IF; LOCK TABLE public.bank_transactions IN SHARE ROW EXCLUSIVE MODE; PERFORM pg_advisory_xact_lock(741928301); IF EXISTS(SELECT 1 FROM public.bank_transactions WHERE gmf_status='sending') THEN RAISE EXCEPTION 'Có thông báo GMF đang gửi; chờ gửi xong rồi reset lại'; END IF; ts:=clock_timestamp(); c:=jsonb_build_object('transactions',(SELECT count(*) FROM public.bank_transactions),'events',(SELECT count(*) FROM public.bank_transaction_events),'notifications',(SELECT count(*) FROM public.notifications WHERE bank_tx_id IS NOT NULL),'push',(SELECT count(*) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.bank_tx_id IS NOT NULL)); INSERT INTO private.fin_reset_backups(reset_at,reset_by,counts,transactions,events,notifications,push_deliveries,operation_start) VALUES(ts,me,c,coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM public.bank_transactions t),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(e)) FROM public.bank_transaction_events e),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(n)) FROM public.notifications n WHERE bank_tx_id IS NOT NULL),'[]'),coalesce((SELECT jsonb_agg(to_jsonb(d)) FROM public.push_deliveries d JOIN public.notifications n ON n.id=d.notification_id WHERE n.bank_tx_id IS NOT NULL),'[]'),(SELECT to_jsonb(s) FROM public.fin_operation_start s)) RETURNING id INTO bid; DELETE FROM public.push_deliveries d USING public.notifications n WHERE n.id=d.notification_id AND n.bank_tx_id IS NOT NULL; DELETE FROM public.notifications WHERE bank_tx_id IS NOT NULL; DELETE FROM public.bank_transaction_events WHERE tx_id IS NOT NULL; DELETE FROM public.bank_transactions WHERE id IS NOT NULL; INSERT INTO public.fin_operation_start(id,started_at,started_by,reset_at) VALUES(true,ts,me,ts) ON CONFLICT(id) DO UPDATE SET started_at=ts,started_by=me,reset_at=ts; RETURN jsonb_build_object('reset_at',ts,'backup_id',bid,'counts',c); END; $$;